def countGoodSubseq(nums, p, queries):
    n = len(nums)
    MAXV = 50000

    # Smallest prime factor sieve, so we can list the distinct primes of any value quickly
    spf = list(range(MAXV + 1))
    i = 2
    while i * i <= MAXV:
        if spf[i] == i:
            for j in range(i * i, MAXV + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1

    def primes_of(x):
        # Distinct prime factors of x
        res = []
        while x > 1:
            q = spf[x]
            res.append(q)
            while x % q == 0:
                x //= q
        return res

    total_idx = n * (n - 1) // 2     # sum of all indices 0..n-1
    div_cnt = [0] * (MAXV + 1)       # div_cnt[q] = how many chosen elements (value / p) are divisible by q
    div_sum = [0] * (MAXV + 1)       # div_sum[q] = sum of the indices of those elements
    cnt_of = [0] * (n + 2)           # cnt_of[v] = number of primes q with div_cnt[q] == v
    crit = [0] * n                   # crit[i] = number of primes whose only non-divisible element is index i
    state = {"c": 0, "num_crit": 0}  # c = number of elements divisible by p, num_crit = indices with crit > 0

    def remove_contrib(q):
        # Take prime q's current contribution out of cnt_of and crit
        v = div_cnt[q]
        if v >= 1:
            cnt_of[v] -= 1
            if v == n - 1:
                idx = total_idx - div_sum[q]   # the unique index NOT divisible by q
                crit[idx] -= 1
                if crit[idx] == 0:
                    state["num_crit"] -= 1

    def add_contrib(q):
        # Put prime q's (updated) contribution back
        v = div_cnt[q]
        if v >= 1:
            cnt_of[v] += 1
            if v == n - 1:
                idx = total_idx - div_sum[q]
                if crit[idx] == 0:
                    state["num_crit"] += 1
                crit[idx] += 1

    def add_element(idx, val):
        # val is divisible by p; track its primes after dividing by p
        state["c"] += 1
        for q in primes_of(val // p):
            remove_contrib(q)
            div_cnt[q] += 1
            div_sum[q] += idx
            add_contrib(q)

    def remove_element(idx, val):
        state["c"] -= 1
        for q in primes_of(val // p):
            remove_contrib(q)
            div_cnt[q] -= 1
            div_sum[q] -= idx
            add_contrib(q)

    # Build the initial structure
    for i in range(n):
        if nums[i] % p == 0:
            add_element(i, nums[i])

    answer = 0
    for idx, val in queries:
        # Remove the old value, install the new one
        if nums[idx] % p == 0:
            remove_element(idx, nums[idx])
        nums[idx] = val
        if val % p == 0:
            add_element(idx, val)

        c = state["c"]
        if c == 0:
            continue
        if c < n:
            # Whole multiple-set is allowed; good iff its GCD (divided by p) is 1,
            # i.e. no prime divides all c elements
            if cnt_of[c] == 0:
                answer += 1
        else:
            # All n elements are multiples of p: need GCD 1 overall AND some index
            # whose removal keeps GCD 1, i.e. an index that is not critical
            if cnt_of[n] == 0 and state["num_crit"] < n:
                answer += 1
    return answer
